{
  ".": "0.44.0",
  "apps/api": "0.43.0",
  "apps/web": "0.46.0",
  "apps/desktop": "0.44.0",
  "apps/tee-worker": "0.31.1",
  "packages/core": "0.31.0",
  "packages/crypto": "0.33.0",
