  "packages/sdk-core": "0.38.0",
  "packages/sdk": "0.37.1",
  "crates/crypto": "0.5.0",
  "crates/core": "0.6.0",
  "crates/api-client": "0.35.0",
  "crates/fuse": "0.8.0",
  "crates/sdk": "0.7.0"
}

