1	// @ts-check
2	/**
3	 * PR Release Preview — analyzes individual PR commits (before squash),
4	 * maps changed files to packages, determines bump level per package,
5	 * detects dependency cascades, and auto-applies release labels.
6	 *
7	 * Environment variables (set by workflow):
8	 *   GITHUB_TOKEN  — GitHub API token
9	 *   PR_NUMBER     — Pull request number
10	 *   GITHUB_REPOSITORY — owner/repo
11	 *
12	 * Uses @actions/core and @actions/github (installed by the workflow).
13	 */
14	
15	import * as core from '@actions/core';
16	import * as github from '@actions/github';
17	import { readFileSync, writeFileSync } from 'node:fs';
18	import { join } from 'node:path';
19	import {
20	  BUMP_LEVELS,
21	  PATH_TO_LABEL,
22	  LABEL_TO_PATHS,
23	  MONOTONIC_PATHS,
24	} from './release-constants.js';
25	
26	// ---------------------------------------------------------------------------
27	// Constants
28	// ---------------------------------------------------------------------------
29	
30	/** Conventional commit regex — matches first line of commit message */
31	const CONVENTIONAL_RE =
32	  /^(?<type>feat|fix|perf|refactor|build|test|docs|style|chore|ci|revert)(?:\((?<scope>[^)]*)\))?(?<breaking>!)?:\s*(?<description>.+)/;
33	
34	/** Commit types that do NOT trigger a version bump (D-39) */
35	const EXEMPT_TYPES = new Set(['docs', 'test', 'chore', 'ci', 'style', 'build', 'revert']);
36	
37	/**
38	 * Map commit type to bump level and label suffix.
39	 * Types not listed here are exempt (no bump).
40	 */
41	const TYPE_TO_BUMP = {
42	  feat: { bump: 'minor', label: 'feat' },
43	  fix: { bump: 'patch', label: 'fix' },
44	  perf: { bump: 'patch', label: 'perf' },
45	  refactor: { bump: 'patch', label: 'refactor' },
46	};
47	
48	/**
49	 * JS dependency graph — production dependencies only (D-24).
50	 * Keys are package paths, values are arrays of dependency paths.
51	 */
52	const JS_DEPS = {
53	  'packages/core': ['packages/crypto'],
54	  'packages/sdk-core': ['packages/api-client', 'packages/core', 'packages/crypto'],
55	  'packages/sdk': ['packages/api-client', 'packages/core', 'packages/crypto', 'packages/sdk-core'],
56	  'apps/web': [
57	    'packages/api-client',
58	    'packages/core',
59	    'packages/crypto',
60	    'packages/sdk',
61	    'packages/sdk-core',
62	  ],
63	  'apps/desktop': ['packages/crypto'],
64	  'apps/tee-worker': ['packages/core', 'packages/crypto', 'packages/sdk-core'],
65	};
66	
67	/**
68	 * Rust dependency graph.
69	 */
70	const RUST_DEPS = {
71	  'crates/core': ['crates/crypto'],
72	  'crates/fuse': ['crates/api-client', 'crates/core', 'crates/crypto'],
73	  'crates/sdk': ['crates/api-client', 'crates/core', 'crates/crypto'],
74	  'apps/desktop': [
75	    'crates/api-client',
76	    'crates/core',
77	    'crates/crypto',
78	    'crates/fuse',
79	    'crates/sdk',
80	  ],
81	};
82	
83	/** API lock group members (D-05) */
84	const API_LOCK_GROUP = ['apps/api', 'packages/api-client', 'crates/api-client'];
85	
86	/** Monotonic versioning apps — patch bumps become minor (D-08, D-13) */
87	const MONOTONIC_APPS = MONOTONIC_PATHS;
88	
89	/** Comment marker for finding/updating the preview comment */
90	const COMMENT_MARKER = '<!-- release-preview -->';
91	
92	// ---------------------------------------------------------------------------
93	// Helpers
94	// ---------------------------------------------------------------------------
95	
96	/**
97	 * Read release-please-config.json and extract package paths (D-37).
98	 * Excludes root "." package from enforcement.
99	 * @returns {string[]}
100	 */
101	function getPackagePaths() {
102	  const configPath = join(process.cwd(), 'release-please-config.json');
103	  const config = JSON.parse(readFileSync(configPath, 'utf8'));
104	  return Object.keys(config.packages).filter((p) => p !== '.');
105	}
106	
107	/**
108	 * Map a file path to its package path using longest-prefix matching.
109	 * @param {string} filePath
110	 * @param {string[]} packagePaths — sorted by length descending
111	 * @returns {string|null}
112	 */
113	function fileToPackage(filePath, packagePaths) {
114	  for (const prefix of packagePaths) {
115	    if (filePath === prefix || filePath.startsWith(prefix + '/')) {
116	      return prefix;
117	    }
118	  }
119	  return null;
120	}
121	
122	/**
123	 * Build reverse dependency map: for each package, which packages depend on it?
124	 * @param {Record<string, string[]>} deps
125	 * @returns {Record<string, string[]>}
126	 */
127	function buildReverseDeps(deps) {
128	  /** @type {Record<string, string[]>} */
129	  const reverse = {};
130	  for (const [pkg, depList] of Object.entries(deps)) {
131	    for (const dep of depList) {
132	      if (!reverse[dep]) reverse[dep] = [];
133	      reverse[dep].push(pkg);
134	    }
135	  }
136	  return reverse;
137	}
138	
139	/**
140	 * Fetch all pages of a paginated GitHub API endpoint.
141	 * @param {ReturnType<typeof github.getOctokit>} octokit
142	 * @param {string} route
143	 * @param {Record<string, unknown>} params
144	 * @returns {Promise<any[]>}
145	 */
146	async function fetchAllPages(octokit, route, params) {
147	  const items = [];
148	  let page = 1;
149	  const perPage = 100;
150	
151	  while (true) {
152	    let response;
153	    try {
154	      response = await octokit.request(route, {
155	        ...params,
156	        per_page: perPage,
157	        page,
158	      });
159	    } catch (err) {
160	      // Rate limiting: retry with exponential backoff
161	      if (err.status === 403 || err.status === 429) {
162	        for (const delay of [1000, 2000, 4000]) {
163	          core.warning(`Rate limited, retrying in ${delay}ms...`);
164	          await new Promise((r) => setTimeout(r, delay));
165	          try {
166	            response = await octokit.request(route, {
167	              ...params,
168	              per_page: perPage,
169	              page,
170	            });
171	            break;
172	          } catch (retryErr) {
173	            if (retryErr.status !== 403 && retryErr.status !== 429) throw retryErr;
174	          }
175	        }
176	        if (!response) throw err;
177	      } else {
178	        throw err;
179	      }
180	    }
181	
182	    items.push(...response.data);
183	    if (response.data.length < perPage) break;
184	    page++;
185	  }
186	
187	  return items;
188	}
189	
190	// ---------------------------------------------------------------------------
191	// Main
192	// ---------------------------------------------------------------------------
193	
194	async function run() {
195	  const token = process.env.GITHUB_TOKEN;
196	  const prNumber = parseInt(process.env.PR_NUMBER, 10);
197	  const [owner, repo] = process.env.GITHUB_REPOSITORY.split('/');
198	
199	  if (!token || !prNumber || !owner || !repo) {
200	    core.setFailed('Missing required environment variables');
201	    return;
202	  }
203	
204	  const octokit = github.getOctokit(token);
205	
206	  // ------ Check for release:none escape hatch ------
207	  const { data: prData } = await octokit.rest.pulls.get({
208	    owner,
209	    repo,
210	    pull_number: prNumber,
211	  });
212	  const existingLabels = prData.labels.map((l) => l.name);
213	
214	  if (existingLabels.includes('release:none')) {
215	    core.info('release:none label present — skipping enforcement and label computation');
216	
217	    // Clear any previously injected release-as entries
218	    const configPath = join(process.cwd(), 'release-please-config.json');
219	    const config = JSON.parse(readFileSync(configPath, 'utf8'));
220	    let cleaned = false;
221	    for (const pkgConfig of Object.values(config.packages)) {
222	      if (pkgConfig['release-as']) {
223	        delete pkgConfig['release-as'];
224	        cleaned = true;
225	      }
226	    }
227	    if (cleaned) {
228	      writeFileSync(configPath, JSON.stringify(config, null, 2) + '\n', 'utf8');
229	      core.info('Cleared stale release-as entries from release-please-config.json');
230	      core.setOutput('config_changed', 'true');
231	    } else {
232	      core.setOutput('config_changed', 'false');
233	    }
234	
235	    // Post a minimal comment
236	    await postOrUpdateComment(
237	      octokit,
238	      owner,
239	      repo,
240	      prNumber,
241	      [
242	        COMMENT_MARKER,
243	        '## Release Preview',
244	        '',
245	        '`release:none` label present — no version bumps for this PR.',
246	      ].join('\n')
247	    );
248	    return;
249	  }
250	
251	  // ------ Section 1: File-to-Package Mapping ------
252	  const packagePaths = getPackagePaths();
253	  // Sort by length descending for longest-prefix match
254	  packagePaths.sort((a, b) => b.length - a.length);
255	
256	  core.info(`Loaded ${packagePaths.length} package paths from release-please-config.json`);
257	
258	  // ------ Section 2: Commit Parsing ------
259	  const commits = await fetchAllPages(
260	    octokit,
261	    'GET /repos/{owner}/{repo}/pulls/{pull_number}/commits',
262	    { owner, repo, pull_number: prNumber }
263	  );
264	
265	  core.info(`Found ${commits.length} commits in PR #${prNumber}`);
266	
267	  /**
268	   * Per-package bump tracking.
269	   * @type {Map<string, {bump: string, label: string, source: string}>}
270	   */
271	  const packageBumps = new Map();
272	
273	  /** Track warnings for non-conventional commits */
274	  const warnings = [];
275	
276	  /** Track commits analyzed per package for exemption logic */
277	  /** @type {Map<string, Set<string>>} */
278	  const packageCommitTypes = new Map();
279	
280	  for (const commit of commits) {
281	    // Skip merge commits — they have 2+ parents and carry no release intent
282	    if (commit.parents && commit.parents.length > 1) continue;
283	
284	    const message = commit.commit.message;
285	    const firstLine = message.split('\n')[0];
286	    const sha = commit.sha;
287	    const shortSha = sha.substring(0, 7);
288	
289	    // Parse conventional commit
290	    const match = firstLine.match(CONVENTIONAL_RE);
291	
292	    // Fetch files changed by this commit
293	    const commitDetail = await octokit.rest.repos.getCommit({
294	      owner,
295	      repo,
296	      ref: sha,
297	    });
298	    const changedFiles = (commitDetail.data.files || []).map((f) => f.filename);
299	
300	    // Map changed files to packages
301	    const touchedPackages = new Set();
302	    for (const file of changedFiles) {
303	      const pkg = fileToPackage(file, packagePaths);
304	      if (pkg) touchedPackages.add(pkg);
305	    }
306	
307	    if (touchedPackages.size === 0) continue; // No versioned packages touched
308	
309	    if (!match) {
310	      // Non-conventional commit touching versioned packages
311	      const pkgList = [...touchedPackages].join(', ');
312	      warnings.push(
313	        `Commit \`${shortSha}\` touches \`${pkgList}\` but has non-conventional message: "${firstLine}"`
314	      );
315	      continue;
316	    }
317	
318	    const type = match.groups.type;
319	    const isBreaking = match.groups.breaking === '!' || message.includes('BREAKING CHANGE:');
320	
321	    for (const pkg of touchedPackages) {
322	      // Track all commit types for exemption logic
323	      if (!packageCommitTypes.has(pkg)) packageCommitTypes.set(pkg, new Set());
324	      packageCommitTypes.get(pkg).add(type);
325	
326	      // Determine bump
327	      let bumpInfo;
328	      if (isBreaking) {
329	        bumpInfo = { bump: 'major', label: 'breaking', source: `breaking commit ${shortSha}` };
330	      } else if (TYPE_TO_BUMP[type]) {
331	        bumpInfo = {
332	          bump: TYPE_TO_BUMP[type].bump,
333	          label: TYPE_TO_BUMP[type].label,
334	          source: `${type} commit ${shortSha}`,
335	        };
336	      } else {
337	        // Exempt type (docs, test, chore, etc.) — no bump
338	        continue;
339	      }
340	
341	      const existing = packageBumps.get(pkg);
342	      if (!existing || BUMP_LEVELS[bumpInfo.bump] > BUMP_LEVELS[existing.bump]) {
343	        packageBumps.set(pkg, bumpInfo);
344	      }
345	    }
346	  }
347	
348	  // ------ Section 3: Auto-Exemptions (D-39) ------
349	  // If ALL commits for a package have only exempt types, that package gets no label
350	  for (const [pkg, types] of packageCommitTypes.entries()) {
351	    const allExempt = [...types].every((t) => EXEMPT_TYPES.has(t));
352	    if (allExempt) {
353	      packageBumps.delete(pkg);
354	    }
355	  }
356	
357	  // ------ Section 4: API Lock Group (D-05) ------
358	  let apiGroupBump = 'none';
359	  let apiGroupLabel = '';
360	  let apiGroupSource = '';
361	
362	  for (const member of API_LOCK_GROUP) {
363	    const bump = packageBumps.get(member);
364	    if (bump && BUMP_LEVELS[bump.bump] > BUMP_LEVELS[apiGroupBump]) {
365	      apiGroupBump = bump.bump;
366	      apiGroupLabel = bump.label;
367	      apiGroupSource = bump.source;
368	    }
369	  }
370	
371	  if (apiGroupBump !== 'none') {
372	    for (const member of API_LOCK_GROUP) {
373	      packageBumps.set(member, {
374	        bump: apiGroupBump,
375	        label: apiGroupLabel,
376	        source: apiGroupSource,
377	      });
378	    }
379	  }
380	
381	  // ------ Section 5: Monotonic Versioning (D-08, D-13) ------
382	  // For web and desktop, patch -> minor (they don't have patch releases)
383	  for (const app of MONOTONIC_APPS) {
384	    const bump = packageBumps.get(app);
385	    if (bump && bump.bump === 'patch') {
386	      packageBumps.set(app, { ...bump, bump: 'minor' });
387	    }
388	  }
389	
390	  // ------ Section 6: Cascade Detection (D-21, D-22, D-23, D-24) ------
391	  const jsReverse = buildReverseDeps(JS_DEPS);
392	  const rustReverse = buildReverseDeps(RUST_DEPS);
393	  const allReverse = {};
394	  for (const [dep, dependents] of Object.entries(jsReverse)) {
395	    allReverse[dep] = [...(allReverse[dep] || []), ...dependents];
396	  }
397	  for (const [dep, dependents] of Object.entries(rustReverse)) {
398	    allReverse[dep] = [...(allReverse[dep] || []), ...dependents];
399	  }
400	
401	  /** @type {Array<{from: string, to: string, fromBump: string, toBump: string}>} */
402	  const cascadeDetails = [];
403	
404	  // Iterate bumped packages and cascade to dependents
405	  // We need to iterate in dependency order (leaves first) to propagate transitively
406	  // Keep cascading until no new bumps are found
407	  let changed = true;
408	  while (changed) {
409	    changed = false;
410	    for (const [pkg, bumpInfo] of [...packageBumps.entries()]) {
411	      const dependents = allReverse[pkg] || [];
412	      for (const dependent of dependents) {
413	        // Cascade rules (D-22):
414	        //   major -> dependent gets at minimum minor
415	        //   minor/patch -> dependent gets at minimum patch
416	        let cascadeBump = 'patch';
417	        if (bumpInfo.bump === 'major') {
418	          cascadeBump = 'minor';
419	        }
420	
421	        const existing = packageBumps.get(dependent);
422	        if (!existing || BUMP_LEVELS[cascadeBump] > BUMP_LEVELS[existing.bump]) {
423	          const wasNew = !existing;
424	          const cascadeLabel = cascadeBump === 'minor' ? 'feat' : 'fix';
425	          packageBumps.set(dependent, {
426	            bump: cascadeBump,
427	            label:
428	              existing?.label && BUMP_LEVELS[existing.bump] >= BUMP_LEVELS[cascadeBump]
429	                ? existing.label
430	                : cascadeLabel,
431	            source: `Cascade (${PATH_TO_LABEL[pkg] || pkg} ${bumpInfo.bump})`,
432	          });
433	          if (wasNew || BUMP_LEVELS[cascadeBump] > BUMP_LEVELS[existing?.bump ?? 'none']) {
434	            cascadeDetails.push({
435	              from: pkg,
436	              to: dependent,
437	              fromBump: bumpInfo.bump,
438	              toBump: cascadeBump,
439	            });
440	            changed = true;
441	          }
442	        }
443	      }
444	    }
445	  }
446	
447	  // Apply monotonic versioning again for cascaded bumps on web/desktop
448	  for (const app of MONOTONIC_APPS) {
449	    const bump = packageBumps.get(app);
450	    if (bump && bump.bump === 'patch') {
451	      packageBumps.set(app, { ...bump, bump: 'minor' });
452	    }
453	  }
454	
455	  // Re-apply API lock group after cascading
456	  apiGroupBump = 'none';
457	  apiGroupLabel = '';
458	  apiGroupSource = '';
459	  for (const member of API_LOCK_GROUP) {
460	    const bump = packageBumps.get(member);
461	    if (bump && BUMP_LEVELS[bump.bump] > BUMP_LEVELS[apiGroupBump]) {
462	      apiGroupBump = bump.bump;
463	      apiGroupLabel = bump.label;
464	      apiGroupSource = bump.source;
465	    }
466	  }
467	  if (apiGroupBump !== 'none') {
468	    for (const member of API_LOCK_GROUP) {
469	      const existing = packageBumps.get(member);
470	      if (!existing || BUMP_LEVELS[apiGroupBump] > BUMP_LEVELS[existing.bump]) {
471	        packageBumps.set(member, {
472	          bump: apiGroupBump,
473	          label: apiGroupLabel,
474	          source: apiGroupSource,
475	        });
476	      }
477	    }
478	  }
479	
480	  // ------ Section 7: Label Application (D-16, D-18) ------
481	
482	  // Collapse package paths to label components (highest bump per component)
483	  /** @type {Map<string, {bump: string, label: string, source: string}>} */
484	  const componentBumps = new Map();
485	
486	  for (const [pkg, bumpInfo] of packageBumps.entries()) {
487	    const component = PATH_TO_LABEL[pkg];
488	    if (!component) continue;
489	
490	    const existing = componentBumps.get(component);
491	    if (!existing || BUMP_LEVELS[bumpInfo.bump] > BUMP_LEVELS[existing.bump]) {
492	      componentBumps.set(component, bumpInfo);
493	    }
494	  }
495	
496	  // Determine label type for each component
497	  /** @type {Map<string, string>} */
498	  const computedLabels = new Map();
499	  for (const [component, bumpInfo] of componentBumps.entries()) {
500	    let labelType;
501	    if (bumpInfo.bump === 'major') {
502	      labelType = 'breaking';
503	    } else {
504	      labelType = bumpInfo.label;
505	    }
506	    computedLabels.set(component, `release:${component}:${labelType}`);
507	  }
508	
509	  // Fetch current labels on the PR
510	  const currentReleaseLabels = existingLabels.filter(
511	    (l) => l.startsWith('release:') && l !== 'release:none'
512	  );
513	
514	  // Determine which existing release labels are manual overrides (D-18)
515	  const manualOverrides = [];
516	
517	  // Group existing labels by component
518	  /** @type {Map<string, string>} */
519	  const existingByComponent = new Map();
520	  for (const label of currentReleaseLabels) {
521	    const parts = label.split(':');
522	    if (parts.length === 3) {
523	      existingByComponent.set(parts[1], label);
524	    }
525	  }
526	
527	  // Labels to add and remove
528	  const labelsToAdd = [];
529	  const labelsToRemove = [];
530	
531	  // Label type → bump level for comparison
532	  const LABEL_BUMP_LEVEL = { fix: 1, perf: 1, refactor: 1, feat: 2, breaking: 3 };
533	
534	  for (const [component, computedLabel] of computedLabels.entries()) {
535	    const existing = existingByComponent.get(component);
536	    if (existing && existing !== computedLabel) {
537	      const existingLevel = LABEL_BUMP_LEVEL[existing.split(':')[2]] ?? 0;
538	      const computedLevel = LABEL_BUMP_LEVEL[computedLabel.split(':')[2]] ?? 0;
539	
540	      if (computedLevel > existingLevel) {
541	        // Computed bump is higher — replace existing label (e.g. fix→feat after force-push)
542	        labelsToRemove.push(existing);
543	        labelsToAdd.push(computedLabel);
544	      } else {
545	        // Existing label is higher or equal — treat as manual override
546	        manualOverrides.push({
547	          component,
548	          existing,
549	          computed: computedLabel,
550	        });
551	
552	        // Feed the manual override back into packageBumps so release-as
553	        // derivation uses the higher label, not the lower commit-derived bump
554	        const overrideType = existing.split(':')[2]; // e.g. 'feat', 'breaking'
555	        const overrideBump =
556	          overrideType === 'breaking' ? 'major' : overrideType === 'feat' ? 'minor' : 'patch';
557	        const overridePaths = LABEL_TO_PATHS[component] || [];
558	        for (const p of overridePaths) {
559	          const current = packageBumps.get(p);
560	          if (!current || BUMP_LEVELS[overrideBump] > BUMP_LEVELS[current.bump]) {
561	            packageBumps.set(p, {
562	              bump: overrideBump,
563	              label: overrideType,
564	              source: `Manual override (${existing})`,
565	            });
566	          }
567	        }
568	      }
569	    } else if (!existing) {
570	      labelsToAdd.push(computedLabel);
571	    }
572	    // If existing matches computed, no action needed
573	  }
574	
575	  // Remove labels for components no longer computed.
576	  // Manual overrides (D-18) still work but must be reapplied after the final commit.
577	  // TODO(deferred): preserve manually-added labels by tracking auto-applied state.
578	  for (const [component, existingLabel] of existingByComponent.entries()) {
579	    if (!computedLabels.has(component)) {
580	      labelsToRemove.push(existingLabel);
581	    }
582	  }
583	
584	  // Apply label changes
585	  for (const label of labelsToAdd) {
586	    try {
587	      await octokit.rest.issues.addLabels({
588	        owner,
589	        repo,
590	        issue_number: prNumber,
591	        labels: [label],
592	      });
593	      core.info(`Added label: ${label}`);
594	    } catch (err) {
595	      core.warning(`Could not add label "${label}": ${err.message}`);
596	    }
597	  }
598	
599	  for (const label of labelsToRemove) {
600	    try {
601	      await octokit.rest.issues.removeLabel({
602	        owner,
603	        repo,
604	        issue_number: prNumber,
605	        name: label,
606	      });
607	      core.info(`Removed label: ${label}`);
608	    } catch (err) {
609	      // Label might not exist — that's fine
610	      if (err.status !== 404) {
611	        core.warning(`Could not remove label "${label}": ${err.message}`);
612	      }
613	    }
614	  }
615	
616	  // ------ Section 7.5: Release-As Injection ------
617	  // Write release-as targets into release-please-config.json on the PR branch.
618	  // When the PR merges, these land on main and release-please picks them up.
619	  const configPath = join(process.cwd(), 'release-please-config.json');
620	  const manifestPath = join(process.cwd(), '.release-please-manifest.json');
621	  const config = JSON.parse(readFileSync(configPath, 'utf8'));
622	  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
623	
624	  // Snapshot base branch release-as entries to avoid clearing inherited targets
625	  // that were set by previously merged PRs but not yet consumed by release-please
626	  /** @type {Record<string, string|undefined>} */
627	  const baseReleaseAs = {};
628	  try {
629	    const { execSync } = await import('node:child_process');
630	    const baseConfig = JSON.parse(
631	      execSync('git show origin/main:release-please-config.json', { encoding: 'utf8' })
632	    );
633	    for (const [p, c] of Object.entries(baseConfig.packages || {})) {
634	      baseReleaseAs[p] = c['release-as'];
635	    }
636	  } catch {
637	    core.info('Could not read base branch config — skipping inherited release-as preservation');
638	  }
639	
640	  /** @type {Array<{path: string, currentVersion: string, targetVersion: string, bumpType: string}>} */
641	  const releaseAsEntries = [];
642	  let configChanged = false;
643	
644	  // Clear release-as entries that THIS PR added (not inherited from base) for packages
645	  // no longer being bumped. Inherited entries from base branch are preserved.
646	  for (const [pkgPath, pkgConfig] of Object.entries(config.packages)) {
647	    if (pkgConfig['release-as'] && !packageBumps.has(pkgPath) && !baseReleaseAs[pkgPath]) {
648	      delete pkgConfig['release-as'];
649	      configChanged = true;
650	      core.info(`Cleared stale release-as for ${pkgPath}`);
651	    }
652	  }
653	
654	  for (const [pkgPath, bumpInfo] of packageBumps.entries()) {
655	    const currentVersion = manifest[pkgPath];
656	    if (!currentVersion || !config.packages[pkgPath]) continue;
657	
658	    const isMonotonic = MONOTONIC_PATHS.has(pkgPath);
659	    const bumpType = bumpInfo.bump;
660	    let effectiveBump = isMonotonic && bumpType === 'patch' ? 'minor' : bumpType;
661	
662	    // Respect bump-minor-pre-major: treat breaking as minor while pre-1.0
663	    const bumpMinorPreMajor = config.packages[pkgPath]['bump-minor-pre-major'] === true;
664	    const parts = currentVersion.split('.').map(Number);
665	    while (parts.length < 3) parts.push(0);
666	    const [major, minor, patch] = parts;
667	    if (major === 0 && effectiveBump === 'major' && bumpMinorPreMajor) {
668	      effectiveBump = 'minor';
669	    }
670	
671	    let targetVersion;
672	    switch (effectiveBump) {
673	      case 'major':
674	        targetVersion = `${major + 1}.0.0`;
675	        break;
676	      case 'minor':
677	        targetVersion = `${major}.${minor + 1}.0`;
678	        break;
679	      case 'patch':
680	        targetVersion = `${major}.${minor}.${patch + 1}`;
681	        break;
682	      default:
683	        continue;
684	    }
685	
686	    // Don't downgrade an existing higher release-as (e.g. from manual label override)
687	    const existingReleaseAs = config.packages[pkgPath]['release-as'];
688	    if (existingReleaseAs && existingReleaseAs !== targetVersion) {
689	      const existingParts = existingReleaseAs.split('.').map(Number);
690	      const targetParts = targetVersion.split('.').map(Number);
691	      while (existingParts.length < 3) existingParts.push(0);
692	      while (targetParts.length < 3) targetParts.push(0);
693	      const existingVal = existingParts[0] * 10000 + existingParts[1] * 100 + existingParts[2];
694	      const targetVal = targetParts[0] * 10000 + targetParts[1] * 100 + targetParts[2];
695	      if (existingVal > targetVal) {
696	        core.info(
697	          `Keeping higher existing release-as ${existingReleaseAs} for ${pkgPath} (computed ${targetVersion})`
698	        );
699	        targetVersion = existingReleaseAs;
700	      }
701	    }
702	    if (existingReleaseAs !== targetVersion) {
703	      config.packages[pkgPath]['release-as'] = targetVersion;
704	      configChanged = true;
705	    }
706	
707	    releaseAsEntries.push({
708	      path: pkgPath,
709	      currentVersion,
710	      targetVersion,
711	      bumpType: effectiveBump,
712	    });
713	  }
714	
715	  if (configChanged) {
716	    writeFileSync(configPath, JSON.stringify(config, null, 2) + '\n', 'utf8');
717	    core.info(
718	      `Updated release-please-config.json with ${releaseAsEntries.length} release-as entries`
719	    );
720	  } else {
721	    core.info('release-please-config.json unchanged — no commit needed');
722	  }
723	  core.setOutput('config_changed', String(configChanged));
724	
725	  // ------ Section 8: PR Comment (D-23) ------
726	  const commentLines = [COMMENT_MARKER, '## Release Preview', ''];
727	
728	  if (componentBumps.size === 0 && warnings.length === 0) {
729	    commentLines.push(
730	      'No version bumps detected. All changes are in unversioned paths or use exempt commit types.'
731	    );
732	  } else {
733	    if (componentBumps.size > 0) {
734	      commentLines.push(
735	        '| Package | Bump | Label | Source |',
736	        '| ------- | ---- | ----- | ------ |'
737	      );
738	
739	      // Sort components alphabetically for stable output
740	      const sortedComponents = [...componentBumps.entries()].sort(([a], [b]) => a.localeCompare(b));
741	
742	      for (const [component, bumpInfo] of sortedComponents) {
743	        const label = computedLabels.get(component);
744	        const isDirect = !bumpInfo.source.startsWith('Cascade');
745	        const source = isDirect ? `Direct (${bumpInfo.label} commit)` : bumpInfo.source;
746	        commentLines.push(`| ${component} | ${bumpInfo.bump} | \`${label}\` | ${source} |`);
747	      }
748	    }
749	
750	    if (cascadeDetails.length > 0) {
751	      commentLines.push('', '### Cascade Details', '');
752	      // Deduplicate cascade details
753	      const seen = new Set();
754	      for (const detail of cascadeDetails) {
755	        const fromLabel = PATH_TO_LABEL[detail.from] || detail.from;
756	        const toLabel = PATH_TO_LABEL[detail.to] || detail.to;
757	        const key = `${fromLabel}->${toLabel}`;
758	        if (seen.has(key)) continue;
759	        seen.add(key);
760	        commentLines.push(
761	          `- \`${fromLabel}\` ${detail.fromBump} -> \`${toLabel}\` ${detail.toBump} (direct dependency)`
762	        );
763	      }
764	    }
765	
766	    if (manualOverrides.length > 0) {
767	      commentLines.push('', '### Manual Overrides', '');
768	      for (const override of manualOverrides) {
769	        commentLines.push(
770	          `- **${override.component}**: keeping manual label \`${override.existing}\` (computed: \`${override.computed}\`)`
771	        );
772	      }
773	    }
774	
775	    if (warnings.length > 0) {
776	      commentLines.push('', '### Warnings', '');
777	      for (const warning of warnings) {
778	        commentLines.push(`- ${warning}`);
779	      }
780	    }
781	  }
782	
783	  await postOrUpdateComment(octokit, owner, repo, prNumber, commentLines.join('\n'));
784	
785	  // ------ Section 9: CI Check Status (D-19) ------
786	  if (warnings.length > 0) {
787	    core.setFailed(
788	      `${warnings.length} commit(s) touching versioned packages have non-conventional messages. ` +
789	        'Fix commit messages or add the `release:none` label to skip enforcement.'
790	    );
791	  }
792	}
793	
794	/**
795	 * Post or update the release preview comment on the PR.
796	 * @param {ReturnType<typeof github.getOctokit>} octokit
797	 * @param {string} owner
798	 * @param {string} repo
799	 * @param {number} prNumber
800	 * @param {string} body
801	 */
802	async function postOrUpdateComment(octokit, owner, repo, prNumber, body) {
803	  // Find existing comment with marker
804	  const comments = await fetchAllPages(
805	    octokit,
806	    'GET /repos/{owner}/{repo}/issues/{issue_number}/comments',
807	    { owner, repo, issue_number: prNumber }
808	  );
809	
810	  const existing = comments.find(
811	    (c) => c.body && c.body.includes(COMMENT_MARKER) && c.user?.login === 'github-actions[bot]'
812	  );
813	
814	  if (existing) {
815	    await octokit.rest.issues.updateComment({
816	      owner,
817	      repo,
818	      comment_id: existing.id,
819	      body,
820	    });
821	    core.info(`Updated release preview comment (ID: ${existing.id})`);
822	  } else {
823	    await octokit.rest.issues.createComment({
824	      owner,
825	      repo,
826	      issue_number: prNumber,
827	      body,
828	    });
829	    core.info('Created release preview comment');
830	  }
831	}
832	
833	// ---------------------------------------------------------------------------
834	// Entry point
835	// ---------------------------------------------------------------------------
836	
837	run().catch((err) => {
838	  core.setFailed(`PR release preview failed: ${err.message}`);
839	});
