    delete c["release-as"]; removed.push(p+"="+man[p]);
  }
}
fs.writeFileSync("release-please-config.json", JSON.stringify(cfg,null,2)+"\n");
console.log("Removed "+removed.length+" stale pins: "+removed.join(", "));
'
